%[text] # Controller and Environment - Simulation Case
model_name = "HarnessModel_CtrlEnv";
load_system(model_name)
sim_in = Simulink.SimulationInput(model_name);

loadLUTData_VehSpdRef_HighSpeed
sim_in = setModelParameter(sim_in, StopTime = "2474");
sim_in = setBlockParameter(sim_in, ...
  model_name + "/Controller and Environment/Vehicle speed reference", ...
  ReferencedSubsystem = "VehSpdRef_FTP75_refsub");

applyToModel(sim_in)

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

signal_names = [
  "Motor torque command"
  "Vehicle speed reference kph"
  "Vehicle speed kph"
  "Motor speed reference"
  "Motor speed"
  ];

for idx = 1 : numel(signal_names) %[output:group:6cefdf52]
  bevutil1.SignalUtil.plotTimedData( TimedData = sim_data, ... %[output:02d49f81] %[output:102ba76c] %[output:09a4e8ab] %[output:5689f668] %[output:14f05693]
    SignalName = signal_names(idx), ... %[output:02d49f81] %[output:102ba76c] %[output:09a4e8ab] %[output:5689f668] %[output:14f05693]
    FigureHeight = 200 ) %[output:02d49f81] %[output:102ba76c] %[output:09a4e8ab] %[output:5689f668] %[output:14f05693]
end  % for %[output:group:6cefdf52]
